-- Phase 47: viral / TikTok-era guitar songs (bedroom pop, modern prog, dream pop), verified per-part tone data.

with target(artist_name, artist_slug, song_title, song_slug, album, release_year) as (
  values
    ('Polyphia','polyphia','Ego Death','ego-death','Remember That You Will Die',2022),
    ('Polyphia','polyphia','ABC','abc','Remember That You Will Die',2022),
    ('Steve Lacy','steve-lacy','Dark Red','dark-red','Steve Lacy''s Demo',2017),
    ('d4vd','d4vd','Romantic Homicide','romantic-homicide','Petals to Thorns',2022),
    ('The Marias','the-marias','No One Noticed','no-one-noticed','Submarine',2024),
    ('wave to earth','wave-to-earth','seasons','seasons','summer flows 0.02',2020),
    ('Men I Trust','men-i-trust','Show Me How','show-me-how','Oncle Jazz',2019),
    ('Mitski','mitski','My Love Mine All Mine','my-love-mine-all-mine','The Land Is Inhospitable and So Are We',2023),
    ('Clairo','clairo','Sofia','sofia','Immunity',2019),
    ('Clairo','clairo','Bags','bags','Immunity',2019),
    ('girl in red','girl-in-red','we fell in love in october','we-fell-in-love-in-october','chapter 2',2018),
    ('Peach Pit','peach-pit','Alrighty Aphrodite','alrighty-aphrodite','Being So Normal',2018),
    ('The Backseat Lovers','the-backseat-lovers','Kilby Girl','kilby-girl','When We Were Friends',2019),
    ('Mac DeMarco','mac-demarco','Ode to Viceroy','ode-to-viceroy','2',2012),
    ('Mac DeMarco','mac-demarco','Freaking Out the Neighborhood','freaking-out-the-neighborhood','2',2012),
    ('TV Girl','tv-girl','Lovers Rock','lovers-rock','French Exit',2014),
    ('Cigarettes After Sex','cigarettes-after-sex','Apocalypse','apocalypse','Cigarettes After Sex',2017),
    ('Title Fight','title-fight','Head in the Ceiling Fan','head-in-the-ceiling-fan','Floral Green',2012),
    ('Beach Fossils','beach-fossils','Sleep Apnea','sleep-apnea','Clash the Truth',2013),
    ('Current Joys','current-joys','Blondie','blondie','A Different Age',2018),
    ('Frank Ocean','frank-ocean','Ivy','ivy','Blonde',2016),
    ('Laufey','laufey','From the Start','from-the-start','Bewitched',2023),
    ('Stephen Sanchez','stephen-sanchez','Until I Found You','until-i-found-you','Angel Face',2021),
    ('The Neighbourhood','the-neighbourhood','Sweater Weather','sweater-weather','I Love You.',2013),
    ('Ricky Montgomery','ricky-montgomery','Line Without a Hook','line-without-a-hook','Montgomery Ricky',2016)
),
ins_artists as (
  insert into public.artists (name, slug, search_text, is_active)
  select distinct artist_name, artist_slug, artist_name, true from target
  on conflict (slug) do update set name = excluded.name, is_active = true
  returning id, slug
)
insert into public.songs (artist_id, title, slug, album, release_year, search_text, is_active)
select a.id, t.song_title, t.song_slug, t.album, t.release_year,
       concat_ws(' ', t.song_title, t.artist_name, t.album), true
from target t join ins_artists a on a.slug = t.artist_slug
on conflict (artist_id, slug) do update set
  title = excluded.title, album = excluded.album, release_year = excluded.release_year,
  is_active = true, updated_at = now();

