  select p.id from public.song_tone_profiles p
  join public.songs s on s.id = p.song_id join public.artists a on a.id = s.artist_id
  join (values
    ('polyphia','ego-death'),('polyphia','abc'),('steve-lacy','dark-red'),('d4vd','romantic-homicide'),
    ('the-marias','no-one-noticed'),('wave-to-earth','seasons'),('men-i-trust','show-me-how'),
    ('mitski','my-love-mine-all-mine'),('clairo','sofia'),('clairo','bags'),('girl-in-red','we-fell-in-love-in-october'),
    ('peach-pit','alrighty-aphrodite'),('the-backseat-lovers','kilby-girl'),('mac-demarco','ode-to-viceroy'),
    ('mac-demarco','freaking-out-the-neighborhood'),('tv-girl','lovers-rock'),('cigarettes-after-sex','apocalypse'),
